function voiceStatusText(){if(!narrator.supported)return t('В этом браузере голос недоступен. Все объявления остаются в чате.','Voice is unavailable in this browser. All announcements remain in chat.');if(!sound)return t('Все звуки выключены кнопкой ♪ в верхней панели.','All audio is muted with the ♪ button in the top bar.');if(!narrator.settings.enabled)return t('Голос ведущего выключен.','Host narration is off.');if(narrator.settings.volume===0)return t('Громкость голоса установлена на ноль.','Voice volume is set to zero.');if(narrator.status==='no-voice')return t('На устройстве не найден русский голос. Установите его в настройках синтеза речи или используйте текст в чате.','No English voice was found on this device. Install one in the speech settings or use the text chat.');if(narrator.status==='needs-click')return t('Нажмите «Проверить голос», чтобы разрешить озвучку.','Press Test voice to activate narration.');if(narrator.status==='error')return t('Не удалось воспроизвести речь. Попробуйте другой голос.','Speech playback failed. Try another voice.');if(narrator.status==='loading-builtin')return t('Готовим встроенный русский голос… При первом включении загрузка может занять немного времени.','Preparing the built-in Russian voice… The first download may take a little time.');if(narrator.status==='ready-builtin')return t('Работает встроенный русский голос. Установка системного голоса не нужна.','The built-in Russian voice is ready. No system voice installation is needed.');if(narrator.status==='loading')return t('Загружаем доступные голоса…','Loading available voices…');if(!narrator.allowed&&page==='game')return t('Нажмите «Слышать ведущего», чтобы включить объявления на своём устройстве.','Press Hear the host to enable announcements on this device.');return t('Озвучиваются только общие объявления ведущего.','Only the host’s public announcements are spoken.');}
