function voiceSettings(){voiceDialogOpen=true;modal(`<span class="eyebrow">${t('Ведущий на связи','Your host is here')}</span><h2>${t('Голос ведущего','Host voice')}</h2><div class="stack"><label class="check"><input id="voiceEnabled" type="checkbox" ${narrator.settings.enabled?'checked':''} ${narrator.supported?'':'disabled'}>${t('Озвучивать объявления','Speak announcements')}</label><label>${t('Голос ведущего','Narrator voice')}<select id="voiceChoice" ${narrator.supported?'':'disabled'}></select></label><label>${t('Громкость','Volume')} <output id="voiceVolumeValue">${Math.round(narrator.settings.volume*100)}%</output><input id="voiceVolume" type="range" min="0" max="100" step="5" value="${Math.round(narrator.settings.volume*100)}"></label><label>${t('Скорость речи','Speech speed')}<select id="voiceRate"><option value="0.85" ${narrator.settings.rate===.85?'selected':''}>${t('Медленно','Slow')}</option><option value="0.96" ${narrator.settings.rate!==.85&&narrator.settings.rate!==1.1?'selected':''}>${t('Обычно','Normal')}</option><option value="1.1" ${narrator.settings.rate===1.1?'selected':''}>${t('Быстро','Fast')}</option></select></label><button data-do="voiceTest" ${narrator.supported?'':'disabled'}>${t('Проверить голос','Test voice')}</button><p id="voiceStatus" role="status" class="hint"></p><p class="hint">${t('Ночь, день, голосование, итоги и предупреждение об окончании времени. Кнопка «Слышать ведущего» управляет голосом на вашем устройстве. Если играете за одним столом, оставьте голос на одном телефоне. Если на устройстве нет русского голоса, автоматически включается встроенный голос «Елена». Его можно выбрать и вручную.','Night, day, voting, results and a time reminder. Hear the host controls narration on your device. At one table, leave narration enabled on one phone. If no Russian system voice is available, the built-in Elena voice is selected automatically. You can also select it manually.')}</p><p class="hint"><a href="vendor/rhvoice/NOTICE.html" target="_blank" rel="noopener">${t('О встроенном голосе','Built-in voice credits')}</a></p></div>`);refreshVoiceOptions();}
function saveVoiceSettings(){narrator.configure({enabled:$('#voiceEnabled').checked,volume:Number($('#voiceVolume').value)/100,rate:Number($('#voiceRate').value),voices:{[lang]:$('#voiceChoice').value}});store.set('narration',narrator.settings);$('#voiceVolumeValue').textContent=Math.round(narrator.settings.volume*100)+'%';updateVoiceStatus();}

